{
  "unit": 48,
  "font": "sans",
  "caption": "Fig. 9.1",
  "points": {
    "A": {"graph": [0.25, 0], "label": "A", "labelDir": "se", "dot": true},
    "B": {"graph": [0.5, 0.707], "label": "B", "labelDir": "n", "dot": true},
    "arrowStart": {"graph": [0.3, 1.6]},
    "arrowEnd": {"graph": [0.5, 1.6]}
  },
  "elements": [
    {
      "type": "axes",
      "x": {
        "min": 0,
        "max": 0.7,
        "step": 0.1,
        "label": "distance / m",
        "minor": 1,
        "numbers": true
      },
      "y": {
        "min": -1.2,
        "max": 1.2,
        "step": 1,
        "label": "displacement / cm",
        "minor": 1,
        "numbers": false
      },
      "grid": "major",
      "mode": "box",
      "sx": 9,
      "sy": 2
    },
    {
      "type": "text",
      "text": "0",
      "at": [0, 0],
      "anchor": "ne",
      "size": "normal"
    },
    {
      "type": "plot",
      "fn": "sin(x * 5 * pi)",
      "domain": [0, 0.7]
    },
    {
      "type": "arrow",
      "from": "arrowStart",
      "to": "arrowEnd",
      "kind": "pointer",
      "label": "direction of travel of wave",
      "labelAt": "mid"
    }
  ]
}

